<template>
  <div>
    <el-button size="small" class="mt-10" type="primary" @click="addData"
      >新增</el-button
    >
    <el-table
      :data="tableData"
      style="width: 100%"
      class="mt-10"
      v-loading="loading"
    >
      <el-table-column type="index" label="序号" align="center" />
      <el-table-column prop="name" label="组态名称" align="center" />
      <el-table-column prop="craete_time" label="创建时间" align="center" />
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button type="text" @click="editConfiguration(scope.row)">
            <i title="查看" class="icon iconf-configuration"></i>
          </el-button>
          <el-button type="text" @click="preview(scope.row)">
            <i title="运行" class="el-icon-video-play"></i>
          </el-button>
          <el-button
            type="text"
            @click="editData(scope.row)"
            class="el-icon-edit"
          ></el-button>
          <el-button
            type="text"
            @click="delData(scope.row)"
            class="el-icon-delete"
            style="color: red"
          ></el-button>
        </template>
      </el-table-column>
    </el-table>
    <pagination
      class="float-right mt-10 mb-10"
      v-show="total > 0"
      :total="total"
      :page.sync="page"
      :limit.sync="size"
      @pagination="getDataList"
      layout="total, prev, pager, next"
      small
    />
    <el-dialog
      :title="visibleTitle"
      :visible.sync="addVisible"
      width="30%"
      :close-on-click-modal="false"
    >
      <el-form
        :model="ruleForm"
        :rules="rules"
        ref="ruleForm"
        label-width="100px"
        class="demo-ruleForm"
      >
        <el-form-item label="组态名称" prop="name">
          <el-input v-model="ruleForm.name"></el-input>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="addVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('ruleForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  data() {
    return {
      tableData: [],
      ruleForm: {},
      rules: {
        name: [{ required: true, message: "请输入", trigger: "blur" }],
      },
      addVisible: false,
      total: 0,
      page: 1,
      size: 10,
      visibleTitle: "新增",
      loading: false,
    };
  },
  created() {
    this.getDataList();
  },
  methods: {
    preview(row) {
      window.open(`/config/preview?id=${row.id}`, "_blank");
    },
    editConfiguration(row) {
      localStorage.setItem("schema", row.info);
      localStorage.setItem(
        "Config",
        JSON.stringify({ id: row.id, name: row.name })
      );
      window.open(`/config/editor?id=${row.id}`, "_blank");
    },
    handleCurrentChange(e) {
      this.page = e;
      this.getDataList();
    },
    delData(row) {
      this.$confirm("是否删除该数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api
            .post("/web/delWebConfig", {
              id: row.id,
            })
            .then(() => {
              this.$message.success("操作成功");
              this.getDataList();
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    editData(row) {
      this.ruleForm = {
        ...row,
      };
      this.visibleTitle = "编辑";
      this.addVisible = true;
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          if (this.ruleForm.id) {
            this.$api.post("/web/updateWebConfig", this.ruleForm).then(() => {
              this.$message.success("操作成功");
              this.addVisible = false;
              this.getDataList();
            });
          } else {
            this.$api.post("/web/addWebConfig", this.ruleForm).then(() => {
              this.$message.success("操作成功");
              this.addVisible = false;
              this.getDataList();
            });
          }
        } else {
          return false;
        }
      });
    },
    addData() {
      this.ruleForm = {};
      this.visibleTitle = "新增";
      this.addVisible = true;
    },
    getDataList() {
      this.loading = true;
      this.$api
        .get(`/web/getWebConfigList?page=${this.page}&size=${this.size}`)
        .then((res) => {
          this.tableData = res.data.data;
          this.total = res.data.total;
        })
        .finally(() => {
          this.loading = false;
        });
    },
  },
};
</script>

